"""Helpers that know the robot, not any task: where an arm's actuators and joints are, and which contacts matter.

    ids = arm_ids(model, "left")                       # actuator, joint, position and velocity addresses of one arm
    contacts_now = make_contact_monitor(model)         # a function: simulation state -> the robot's unexpected contacts
    pairs = contacts_now(data)                         # [(name_a, name_b), ...]

The contact monitor counts a contact when exactly one of its two geoms belongs to the robot (the base link and everything attached to it) and
neither is the floor, or when two geoms of the robot touch each other with penetration (the two fingers of a hand touching each other do not
count). It is used by the episode runner (src/episode_runner.py), whatever the task.
"""

import mujoco
import numpy as np


def arm_ids(model, side):
    """Looks up the actuators and joints of one arm's 7 joints, and its gripper.

    Args:
        model (mujoco.MjModel): A model with the actuators "<side>_joint1_ctrl" to "<side>_joint7_ctrl" and
            "<side>_gripper_ctrl" (the one gripper actuator, on openarm_<side>_finger_joint1; finger_joint2 follows it through a joint equality).
        side (str): "left" or "right".

    Returns:
        dict: With the keys
            "act" (list of int): Actuator ids of the 7 joints, in joint order.
            "jnt" (list of int): Joint ids of those actuators.
            "qadr" (list of int): Addresses of the joints in qpos.
            "vadr" (list of int): Addresses of the joints in qvel.
            "gripper" (int): Actuator id of the gripper (it moves both fingers).
            "finger_jnt" (list of int): Joint ids of the two fingers, finger_joint1 (the actuated one) first.
    """
    act = [model.actuator(f"{side}_joint{i}_ctrl").id for i in range(1, 8)]
    jnt = [int(model.actuator_trnid[a, 0]) for a in act]
    qadr = [int(model.jnt_qposadr[j]) for j in jnt]
    vadr = [int(model.jnt_dofadr[j]) for j in jnt]
    gripper = model.actuator(f"{side}_gripper_ctrl").id
    finger_jnt = [model.joint(f"openarm_{side}_finger_joint{k}").id for k in (1, 2)]
    return {"act": act, "jnt": jnt, "qadr": qadr, "vadr": vadr, "gripper": gripper, "finger_jnt": finger_jnt}


# ----------------------------------------------------------------------------------------------------------
# Loading
# ----------------------------------------------------------------------------------------------------------


def _body_set(model, root_name):
    """Collects the ids of a body and all its descendants.

    Args:
        model (mujoco.MjModel): The compiled model.
        root_name (str): Name of the root body.

    Returns:
        set[int]: Ids of the root body and of every body below it in the kinematic tree.
    """
    root = model.body(root_name).id
    out = set()
    for b in range(model.nbody):
        c = b
        while c > 0:
            if c == root:
                out.add(b)
                break
            c = int(model.body_parentid[c])
    return out


def make_contact_monitor(model, robot_root="base_link", finger_marker="finger"):
    """Builds a function that lists the robot's unexpected contacts in a simulation state.

    Args:
        model (mujoco.MjModel): The compiled model.
        robot_root (str): Name of the body at the root of the robot's kinematic tree. Defaults to "base_link".
        finger_marker (str): Text that marks a finger body name; contacts between two fingers are ignored. Defaults to "finger".

    Returns:
        callable: contacts_now(data) -> list[tuple[str, str]], the (geom or body name, geom or body name) pairs of the contacts in
        `data` that count, as described in the module docstring.
    """
    robot_bodies = _body_set(model, robot_root)
    in_robot = np.zeros(model.ngeom, bool)
    for g in range(model.ngeom):
        in_robot[g] = int(model.geom_bodyid[g]) in robot_bodies
    floor = np.array([int(model.geom_bodyid[g]) == 0 for g in range(model.ngeom)])
    is_finger = np.array([finger_marker in model.body(int(model.geom_bodyid[g])).name for g in range(model.ngeom)])

    def contacts_now(data):
        """Lists the counted contacts of the current state of `data`.

        Args:
            data (mujoco.MjData): Simulation state, after mj_step or mj_forward.

        Returns:
            list[tuple[str, str]]: Name pairs of the counted contacts (empty when there are none).
        """
        n = data.ncon
        if n == 0:
            return []
        g1, g2 = data.contact.geom1[:n], data.contact.geom2[:n]
        mask = (in_robot[g1] != in_robot[g2]) & ~floor[g1] & ~floor[g2]
        mask |= in_robot[g1] & in_robot[g2] & ~(is_finger[g1] & is_finger[g2]) & (data.contact.dist[:n] < 0)
        return [(model.geom(int(a)).name or model.body(int(model.geom_bodyid[a])).name,
                 model.geom(int(b)).name or model.body(int(model.geom_bodyid[b])).name) for a, b in zip(g1[mask], g2[mask])]

    return contacts_now
